    const bottomBox = { left: pw.boxLeft, top: pw.cardTop }, topBox = { left: 850, top: 92 }, topRight = { left: 1106, top: 92 };
    const h = call.offsetHeight, w = call.offsetWidth;
    const rects = $$(inst.el, '.glab').map((e) => ({ l: e.offsetLeft - 6, r: e.offsetLeft + e.offsetWidth + 6, t: e.offsetTop - 6, b: e.offsetTop + e.offsetHeight + 6 }));
