  const cur = (e) => getComputedStyle(e).opacity;
  call.animate([{ opacity: cur(call) }, { opacity: 0 }], { duration: 200, easing: 'ease-in', fill: 'forwards' });
  lead.animate([{ opacity: cur(lead) }, { opacity: 0 }], { duration: 160, fill: 'forwards' });
