  layer.appendChild(c);
  c.animate([{ opacity: 0, transform: 'scale(.3)' }, { opacity: 1, transform: 'scale(1.15)', offset: 0.35 }, { opacity: 0, transform: 'scale(1.5)' }], { duration: 440, easing: 'ease-out' }).onfinish = () => c.remove();
